{
  "actions": [
    {
      "action": "Separate findings by population and scope",
      "mechanism": "Structured scope prevents similar wording from collapsing findings about different populations into one apparent contradiction.",
      "implementation": "Attach exact stored passage IDs, population, outcome, timeframe, and finding direction to each claim. Mark unstated scope as unspecified.",
      "check": "Enter opposing findings for adults and adolescents; verify separate claims and a visible population difference survive summarization.",
      "risk": "Inferred scope could misrepresent passages; require confirmation of extracted fields."
    },
    {
      "action": "Expose disagreement in a passage comparison panel",
      "mechanism": "Side-by-side evidence distinguishes opposing findings within matching scopes from findings whose scopes differ.",
      "implementation": "Add claim-pair comparison showing scope differences and exact linked passages in an in-workspace drawer; allow users to mark relationships unresolved.",
      "check": "Compare opposing adult and adolescent claims, then matching-population opposites; verify scope difference and disagreement remain distinguishable and originals open inline.",
      "risk": "Automated pairing may miss relevant claims; retain manual comparison."
    },
    {
      "action": "Keep missing evidence separate from opposing evidence",
      "mechanism": "Explicit evidence states prevent an empty search or unfilled slot from becoming a negative finding.",
      "implementation": "Separate supporting passages, opposing passages, and no linked evidence. Require exact passage IDs for either evidence-bearing category; restrict lookup to stored passages.",
      "check": "Remove every opposing passage; verify the interface says no opposing evidence linked, not that the claim is confirmed.",
      "risk": "Labels describe this board, not all available research."
    },
    {
      "action": "Validate scope and citations before briefing export",
      "mechanism": "Statement-level checks keep compression from silently broadening claims or deleting recorded disagreements.",
      "implementation": "Build briefing statements from supplied passages with exact passage IDs. Flag omitted population qualifiers and linked opposing findings; require revision or explicit qualification.",
      "check": "Draft a universal statement from opposing adult and adolescent findings; verify export requires scoped wording and accessible citations for both findings.",
      "risk": "Semantic checks can miss overreach; preserve human review without ranking source truth."
    }
  ],
  "abstention_reason": ""
}
